body.value:
(* Linear scaling of the 4-20mA raw signal to engineering units. *)
PV := Raw_Signal * Scaling_Slope + Scaling_Offset;
(* Wire-break style fault: a healthy 4-20mA loop never drops below ~2mA. *)
General_Fault := Alarm_Enable AND (Raw_Signal < 2.0);
High_Alarm := Alarm_Enable AND (PV > PV_High);
Low_Alarm := Alarm_Enable AND (PV < PV_Low);

Bool_Out := Bool_In;
Alarm_Active := (Alarm_OnTrue AND Bool_In) OR (Alarm_OnFalse AND NOT Bool_In);
IF Reset_Latch THEN
    Latched_Status := FALSE;
ELSIF Latch_Enable AND Alarm_Active THEN
    Latched_Status := TRUE;
END_IF;

(* Pass-through of the field contact (debounce not modeled). *)
DI_Out := DI_Raw;
Fault_State := FALSE;

ActiveIsA := NOT AlternateEnable;
IF Enable AND StartRequest AND NOT Inhibit THEN
    CmdPumpA := ActiveIsA AND NOT PumpA_Fault;
    CmdPumpB := (NOT ActiveIsA OR PumpA_Fault) AND NOT PumpB_Fault;
ELSE
    CmdPumpA := FALSE;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpA THEN
    CmdPumpA := Enable AND NOT Inhibit;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpB THEN
    CmdPumpA := FALSE;
    CmdPumpB := Enable AND NOT Inhibit;
END_IF;
SwitchedDueToDuty := DutyElapsed;
SwitchedDueToFailure := PumpA_Fault OR PumpB_Fault;
Alarm_FailedStart_A := PumpA_Fault;
Alarm_FailedStart_B := PumpB_Fault;
Alarm_NoAvailablePump := PumpA_Fault AND PumpB_Fault;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_HighSpeed := Motor_Start_Out AND Speed_High_Cmd;
FB_LowSpeed := Motor_Start_Out AND Speed_Low_Cmd AND NOT Speed_High_Cmd;
FB_Trip := FALSE;
Alarm_Speed_Error := Speed_High_Cmd AND Speed_Low_Cmd;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_Trip := FALSE;
Alarm_Start_Fail := FALSE;
Alarm_Stop_Fail := FALSE;

IF Inhibit OR Stop_Cmd THEN
    FB_Running := FALSE;
ELSIF Start_Cmd THEN
    FB_Running := TRUE;
END_IF;
IF FB_Running THEN
    Speed_Out := Speed_SP;
ELSE
    Speed_Out := 0.0;
END_IF;
FB_Ready := NOT Inhibit;
FB_Fault := FALSE;
FB_ActualSpeed := Speed_Out;
Alarm_Speed_Deviation := FALSE;
Alarm_Comm_Fail := FALSE;

PV_High_Alarm := PV > PV_High;
PV_Low_Alarm := PV < PV_Low;
Deviation_Alarm := ABS(SP - PV) > Deviation_Limit;
(* Bounded proportional control law (single-block, stateless). *)
IF Inhibit THEN
    XOUT := MV_MIN;
ELSIF AUTO THEN
    XOUT := LIMIT(MV_MIN, X0 + KP * (SP - PV), MV_MAX);
ELSE
    XOUT := X0;
END_IF;

IF PrimaryPV > 0.0 THEN
    ActiveRatio := SecondaryPV / PrimaryPV;
ELSE
    ActiveRatio := 0.0;
END_IF;
RatioErr := ActiveRatio - RatioSP;
IF Inhibit THEN
    SlaveSP := MV_MIN;
ELSIF Auto THEN
    SlaveSP := LIMIT(MV_MIN, PrimaryPV * RatioSP + Bias, MV_MAX);
ELSE
    SlaveSP := ManOut;
END_IF;

IF IN <= Split_Point THEN
    OUT1 := Output1_End;
    OUT2 := Output2_Start;
ELSE
    OUT1 := Output1_Start;
    OUT2 := Output2_End;
END_IF;

IF Inhibit THEN
    Valve_Position := Close_Limit;
ELSIF Manual_Mode THEN
    Valve_Position := LIMIT(Close_Limit, Manual_Position, Open_Limit);
ELSE
    Valve_Position := LIMIT(Close_Limit, Control_Signal, Open_Limit);
END_IF;
Feedback_Pos := Valve_Position;
Valve_Moving := FALSE;
Position_Error := FALSE;
Alarm := Inhibit;

IF Inhibit THEN
    Valve_Open_Out := FALSE;
    Valve_Close_Out := TRUE;
ELSE
    Valve_Open_Out := Open_Cmd AND NOT Close_Cmd;
    Valve_Close_Out := Close_Cmd OR NOT Open_Cmd;
END_IF;
FB_Opened := Valve_Open_Out;
FB_Closed := NOT Valve_Open_Out;
Alarm_Position_Error := FALSE;
Alarm_General := Inhibit;

Voted_Output := (Input1 + Input2 + Input3) / 3.0;
Sensor1_Fault := FALSE;
Sensor2_Fault := FALSE;
Sensor3_Fault := FALSE;
Alarm_Voting_Error := FALSE;
Healthy_Sensors_Count := 3;

FT_101(
    Scaling_Slope := 31.25,
    Scaling_Offset := -125.0,
    Alarm_Enable := TRUE);
LS_101(
    PV_High := 8.5,
    PV_Low := 1.5,
    Scaling_Slope := 0.625,
    Scaling_Offset := -2.5,
    Alarm_Enable := TRUE);
PIC_101(
    AUTO := TRUE,
    PV := LS_101.PV,
    SP := 5.5,
    MV_MIN := 30.0,
    MV_MAX := 90.0,
    X0 := 0.0,
    KP := -2.0,
    TR := 1.5,
    TD := 0.3,
    Deviation_Limit := 0.1);
P101_LevelTrips_OR := PIC_101.PV_Low_Alarm OR PIC_101.PV_High_Alarm OR LS_101.High_Alarm;
P101_LevelTrips_NOT := NOT P101_LevelTrips_OR;
PumpRunEnable_AND := P101_LevelTrips_NOT;
StartA_NOT := NOT PumpRunEnable_AND;
P_101A(
    Start_Cmd := PumpRunEnable_AND,
    Stop_Cmd := StartA_NOT,
    Speed_SP := PIC_101.XOUT,
    Inhibit := P101_LevelTrips_OR);
P101A_Running_NOT := NOT P_101A.FB_Running;
P101A_Failure_OR := P_101A.FB_Fault OR P101A_Running_NOT;
P101B_Start_AND := PumpRunEnable_AND AND P101A_Failure_OR;
StartB_NOT := NOT P101B_Start_AND;
P_101B(
    Start_Cmd := P101B_Start_AND,
    Stop_Cmd := StartB_NOT,
    Speed_SP := PIC_101.XOUT,
    Inhibit := P101_LevelTrips_OR);
LS101_HighAlarm_NOT := NOT LS_101.High_Alarm;
XV_101(
    Open_Cmd := LS101_HighAlarm_NOT,
    Close_Cmd := LS_101.High_Alarm);
BS101_Disable_OR := PIC_101.PV_Low_Alarm OR LS_101.Low_Alarm;
BS_101(
    Bool_In := BS101_Disable_OR);
VG101_Inhibit_OR := LS_101.Low_Alarm OR FT_101.Low_Alarm;
VG_101(
    Inhibit := VG101_Inhibit_OR);
PID_Output_Positive_GT := (0.0 > 0.0);

(* Outputs published to other sections / HMI. *)
P101_LevelTrips_Active := P101_LevelTrips_OR;
VG101_Inhibit_Active := VG101_Inhibit_OR;
BS101_Disable_Active := BS101_Disable_OR;
P_101A_Start_Cmd := PumpRunEnable_AND;
P_101B_Start_Cmd := P101B_Start_AND;
LS_101_WetWellLevel_PV_m := LS_101.PV;
FT_101_InfluentFlow_PV_m3ph := FT_101.PV;
PIC_101_WetWellLevel_MV_Pct := PIC_101.XOUT;
P_101A_Speed_Command_Pct := P_101A.Speed_Out;
P_101B_Speed_Command_Pct := P_101B.Speed_Out;

FT_301(
    Alarm_Enable := TRUE);
FT_302(
    Alarm_Enable := TRUE);
LS_301(
    PV_High := 5.0,
    PV_Low := 2.0,
    Alarm_Enable := TRUE);
PS_301();
SS_301();
FlowAboveCutoff_GT := (FT_301.PV > 50.0);
MasterInhibit_OR := LS_301.High_Alarm OR LS_301.Low_Alarm OR FT_301.High_Alarm OR FT_301.Low_Alarm OR FT_301.General_Fault OR FT_302.High_Alarm OR FT_302.Low_Alarm OR FT_302.General_Fault OR FIC_302.Deviation_Alarm OR FV_102.Position_Error OR FV_102.Alarm OR SS_301.DI_Out;
FFIC_303(
    Auto := FlowAboveCutoff_GT,
    PrimaryPV := FT_301.PV,
    SecondaryPV := FT_302.PV,
    RatioSP := 0.3,
    Bias := 0.0,
    TrimKp := 0.0,
    TrimTi := T#0s,
    MV_MIN := 0.0,
    MV_MAX := 200.0,
    Inhibit := MasterInhibit_OR);
FIC_302(
    AUTO := FlowAboveCutoff_GT,
    PV := FT_302.PV,
    SP := FFIC_303.SlaveSP,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    Deviation_Limit := 10.0,
    Inhibit := MasterInhibit_OR);
FV_102(
    Control_Signal := FIC_302.XOUT,
    Manual_Mode := MasterInhibit_OR,
    Manual_Position := 0.0,
    Inhibit := MasterInhibit_OR);

(* Outputs published to other sections / HMI. *)
FT301_InfluentFlow_PV := FT_301.PV;
FT302_SludgeFlow_PV := FT_302.PV;
LS301_WeirLevel_PV := LS_301.PV;
PS301_SludgePressure_PV := PS_301.PV;
FT302_SludgeFlow_SP := FFIC_303.SlaveSP;

LS_601();
CL_601B(
    Start_Cmd := CL_601A_CL_601B.CmdPumpB,
    Start_Delay := T#5s,
    MinRunTime := T#30m,
    Inhibit := LS_601.DI_Out);
ClarifierAnyRunning_OR := CL_601A.FB_Running OR CL_601B.FB_Running;
Clar_DutyTimer_TON(
    IN := ClarifierAnyRunning_OR,
    PT := T#72h);
Clar_MinRunTimer_TON(
    IN := ClarifierAnyRunning_OR,
    PT := T#30m);
ClarifierNoneRunning_NOT := NOT ClarifierAnyRunning_OR;
Clar_SwitchoverDelay_TON(
    IN := ClarifierNoneRunning_NOT,
    PT := T#10s);
CL_601A_CL_601B(
    Enable := TRUE,
    StartRequest := TRUE,
    AlternateEnable := TRUE,
    DutyElapsed := Clar_DutyTimer_TON.Q,
    MinRunElapsed := Clar_MinRunTimer_TON.Q,
    SwitchoverDelayElapsed := Clar_SwitchoverDelay_TON.Q,
    PumpA_RunFB := CL_601A.FB_Running,
    PumpB_RunFB := CL_601B.FB_Running,
    PumpA_Fault := CL_601A.FB_Trip,
    PumpB_Fault := CL_601B.FB_Trip,
    Inhibit := LS_601.DI_Out);
CL_601A(
    Start_Cmd := CL_601A_CL_601B.CmdPumpA,
    Start_Delay := T#5s,
    MinRunTime := T#30m,
    Inhibit := LS_601.DI_Out);
PT_601A(
    PV_Low := 25.0,
    Alarm_Enable := TRUE);
PS601A_Inhibit_OR := PT_601A.Low_Alarm OR LS_601.DI_Out;
PT_601B(
    PV_Low := 25.0,
    Alarm_Enable := TRUE);
PS601B_Inhibit_OR := PT_601B.Low_Alarm OR LS_601.DI_Out;
PS_601B(
    Start_Cmd := PS_601A_PS_601B.CmdPumpB,
    Start_Delay := T#5s,
    MinRunTime := T#30m,
    Inhibit := PS601B_Inhibit_OR);
PumpAnyRunning_OR := PS_601A.FB_Running OR PS_601B.FB_Running;
Pump_DutyTimer_TON(
    IN := PumpAnyRunning_OR,
    PT := T#72h);
Pump_MinRunTimer_TON(
    IN := PumpAnyRunning_OR,
    PT := T#30m);
PumpNoneRunning_NOT := NOT PumpAnyRunning_OR;
Pump_SwitchoverDelay_TON(
    IN := PumpNoneRunning_NOT,
    PT := T#10s);
PS_601A_PS_601B(
    Enable := TRUE,
    StartRequest := TRUE,
    AlternateEnable := TRUE,
    DutyElapsed := Pump_DutyTimer_TON.Q,
    MinRunElapsed := Pump_MinRunTimer_TON.Q,
    SwitchoverDelayElapsed := Pump_SwitchoverDelay_TON.Q,
    PumpA_RunFB := PS_601A.FB_Running,
    PumpB_RunFB := PS_601B.FB_Running,
    PumpA_Fault := PS_601A.FB_Trip,
    PumpB_Fault := PS_601B.FB_Trip,
    Inhibit := LS_601.DI_Out);
PS_601A(
    Start_Cmd := PS_601A_PS_601B.CmdPumpA,
    Start_Delay := T#5s,
    MinRunTime := T#30m,
    Inhibit := PS601A_Inhibit_OR);
VS_601A(
    Open_Limit := 100.0,
    Close_Limit := 0.0);
VS_601B(
    Open_Limit := 100.0,
    Close_Limit := 0.0);

(* Outputs published to other sections / HMI. *)
PT_601A_DischargePressure_PV := PT_601A.PV;
PT_601B_DischargePressure_PV := PT_601B.PV;
CL_601_ActiveIsA := CL_601A_CL_601B.ActiveIsA;
PS_601_ActiveIsA := PS_601A_PS_601B.ActiveIsA;

FT_801(
    Scaling_Slope := 62.5,
    Scaling_Offset := -250.0,
    Alarm_Enable := TRUE);
XV_106(
    Timeout := T#5s);
ValveNotOpen := NOT XV_106.FB_Opened;
CL_801_Inh_OR1 := ValveNotOpen OR FT_801.Low_Alarm;
XV_106_AnyAlarm := XV_106.Alarm_Position_Error OR XV_106.Alarm_General;
CL_801_Inh_OR2 := CL_801_Inh_OR1 OR XV_106_AnyAlarm;
LV_105(
    Timeout := T#5s);
LV_105_AnyAlarm := LV_105.Position_Error OR LV_105.Alarm;
CL_801_Inh_OR3 := CL_801_Inh_OR2 OR LV_105_AnyAlarm;
CL_801(
    Speed_SP := FIC_101.SlaveSP,
    Inhibit := CL_801_Inh_OR3);
CL_RatioMaxCalc := FT_801.PV * 3.0;
CL_RatioMinCalc := FT_801.PV * 2.0;
FT_801_AnyFault_OR1 := FT_801.Low_Alarm OR FT_801.High_Alarm;
FT_801_AnyFault_OR2 := FT_801_AnyFault_OR1 OR FT_801.General_Fault;
FIC_101(
    Auto := TRUE,
    PrimaryPV := FT_801.PV,
    SecondaryPV := CL_801.FB_ActualSpeed,
    RatioSP := 2.5,
    MV_MIN := CL_RatioMinCalc,
    MV_MAX := CL_RatioMaxCalc,
    Inhibit := FT_801_AnyFault_OR2);
CL_NotRunning := NOT CL_801.FB_Running;
DC_801_Inh_OR1 := LV_105_AnyAlarm OR FT_801.Low_Alarm;
DC_801_Inh_OR2 := DC_801_Inh_OR1 OR CL_NotRunning;
DC_801(
    Speed_SP := FIC_102.SlaveSP,
    Inhibit := DC_801_Inh_OR2);
DC_RatioMaxCalc := FT_801.PV * 1.5;
DC_RatioMinCalc := FT_801.PV * 1.0;
FIC_102_Inh_OR1 := FT_801_AnyFault_OR2 OR CL_NotRunning;
FIC_102(
    Auto := TRUE,
    PrimaryPV := FT_801.PV,
    SecondaryPV := DC_801.FB_ActualSpeed,
    RatioSP := 1.2,
    MV_MIN := DC_RatioMinCalc,
    MV_MAX := DC_RatioMaxCalc,
    Inhibit := FIC_102_Inh_OR1);
ChemActive := CL_801.FB_Running OR DC_801.FB_Running;
UV_801(
    Inhibit := ChemActive);

(* Outputs published to other sections / HMI. *)
FT_801_EffluentFlow_PV := FT_801.PV;
CL_801_ChlorineFlow_SP := FIC_101.SlaveSP;
DC_801_DechlorFlow_SP := FIC_102.SlaveSP;
XV_106_FullyOpen_FB := XV_106.FB_Opened;
CL_801_Running_FB := CL_801.FB_Running;
DC_801_Running_FB := DC_801.FB_Running;

FT_901(
    Alarm_Enable := TRUE);
LS_901(
    PV_High := 90.0,
    Alarm_Enable := TRUE);
FlowLessThan15_GT := (REAL#15.0 > FT_901.PV);
FailCondA_AND := P_901A.FB_Running AND FlowLessThan15_GT;
FailA_TON(
    IN := FailCondA_AND,
    PT := T#10s);
PumpA_Inhibit_OR := LS_901.Low_Alarm OR FailA_TON.Q OR P_901A.FB_Trip;
LevelAbove85_GT := (LS_901.PV > REAL#85.0);
FailCondB_AND := P_901B.FB_Running AND FlowLessThan15_GT;
FailB_TON(
    IN := FailCondB_AND,
    PT := T#10s);
PumpB_Inhibit_OR := LS_901.Low_Alarm OR FailB_TON.Q OR P_901B.FB_Trip;
StartCmdB_OR := LevelAbove85_GT OR P_901AB.CmdPumpB;
P_901B(
    Start_Cmd := StartCmdB_OR,
    MinRunTime := T#30m,
    Inhibit := PumpB_Inhibit_OR);
AnyRunning_OR := P_901A.FB_Running OR P_901B.FB_Running;
DutyTimer_TON(
    IN := AnyRunning_OR,
    PT := T#48h);
LevelAbove60_GT := (LS_901.PV > REAL#60.0);
LevelAbove40_GT := (LS_901.PV > REAL#40.0);
StartBand_AND := AnyRunning_OR AND LevelAbove40_GT;
StartRequest_OR := LevelAbove60_GT OR StartBand_AND;
Failure_OR := FailA_TON.Q OR FailB_TON.Q;
SwitchoverDelay_TON(
    IN := Failure_OR,
    PT := T#5s);
P_901AB(
    Enable := TRUE,
    StartRequest := StartRequest_OR,
    AlternateEnable := TRUE,
    DutyElapsed := DutyTimer_TON.Q,
    SwitchoverDelayElapsed := SwitchoverDelay_TON.Q,
    PumpA_RunFB := P_901A.FB_Running,
    PumpB_RunFB := P_901B.FB_Running,
    PumpA_Fault := FailA_TON.Q,
    PumpB_Fault := FailB_TON.Q);
StartCmdA_OR := LevelAbove85_GT OR P_901AB.CmdPumpA;
P_901A(
    Start_Cmd := StartCmdA_OR,
    MinRunTime := T#30m,
    Inhibit := PumpA_Inhibit_OR);
BothPumpsFailed_AND := FailA_TON.Q AND FailB_TON.Q;
XV_102(
    Inhibit := BothPumpsFailed_AND);

(* Outputs published to other sections / HMI. *)
FT_901_FlowRate := FT_901.PV;
LS_901_LevelPercent := LS_901.PV;
P_901A_Running := P_901A.FB_Running;
P_901B_Running := P_901B.FB_Running;
P_901AB_DutyActiveIsA := P_901AB.ActiveIsA;
P_901AB_SwitchedDueToDuty := P_901AB.SwitchedDueToDuty;
P_901AB_SwitchedDueToFailure := P_901AB.SwitchedDueToFailure;

FIT_104(
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
FIC_106(
    AUTO := TRUE,
    PV := CD_1001.FB_ActualSpeed,
    SP := FFIC_107.SlaveSP,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    Deviation_Limit := 3.0);
PV_101(
    Open_Limit := 100.0,
    Close_Limit := 0.0);
XV_102();
PumpOpenedInverter := NOT XV_102.FB_Opened;
PumpInhibitAggregator := PumpOpenedInverter OR FIT_104.Low_Alarm OR FIT_104.General_Fault OR XV_102.Alarm_General OR XV_102.Alarm_Position_Error OR PV_101.Alarm OR PV_101.Position_Error OR CD_1001.Alarm_Comm_Fail OR CD_1001.FB_Fault OR CD_1001.Alarm_Speed_Deviation;
CD_1001(
    Speed_SP := FIC_106.XOUT,
    Inhibit := PumpInhibitAggregator);
RatioCtrlInhibitAggregator := FIT_104.Low_Alarm OR FIT_104.High_Alarm OR FIT_104.General_Fault OR CD_1001.FB_Fault OR CD_1001.Alarm_Comm_Fail OR CD_1001.Alarm_Speed_Deviation;
FFIC_107(
    Auto := TRUE,
    PrimaryPV := FIT_104.PV,
    SecondaryPV := CD_1001.FB_ActualSpeed,
    RatioSP := 2.5,
    Bias := 0.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    Inhibit := RatioCtrlInhibitAggregator);

(* Outputs published to other sections / HMI. *)
FIT_104_InfluentFlow_PV := FIT_104.PV;
FIC_106_SP_From_FFIC_107 := FFIC_107.SlaveSP;
